arguments.command:
cat > src/CheckoutPricing.Application/CheckoutCalculator.cs <<'E'
namespace CheckoutPricing.Application;

public enum CustomerTier { Standard, Gold }

public sealed class CheckoutCalculator
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal subtotal) =>
        throw new NotImplementedException("Loyalty discount is not implemented.");
}
E
cat > tests/CheckoutPricing.UnitTests/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Application;

namespace CheckoutPricing.UnitTests;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void GoldCustomerReceivesTheApprovedDiscount()
    {
        var total = new CheckoutCalculator().CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, total);
    }
}
E
dotnet test tests/CheckoutPricing.UnitTests 2>&1 | grep -E "error|Failed|Assert|Exception|Passed!|Failed!" | head

